function singleNumber(nums: number[]): number {
  // x ^ x = 0 и x ^ 0 = x, а порядок XOR не важен.
  // Поэтому все пары взаимно уничтожатся, останется одиночный элемент
  let result = 0;

  for (const num of nums) {
    result ^= num;
  }

  return result;
}

// Время: O(n) — один проход
// Память: O(1)
